def most_common(items):
    if not items:
        return None

    # Count the occurrences of each item
    item_counts = {}
    for item in items:
        if item in item_counts:
            item_counts[item] += 1
        else:
            item_counts[item] = 1

    # Find the item with the maximum count
    max_count = max(item_counts.values())
    most_common_item = [item for item, count in item_counts.items() if count == max_count][0]

    return most_common_item
```

